using System;

internal static class JNukePrivate413Crypto
{
    // MESMAS CHAVES do encryptor privado. Nao altere somente um dos lados.
    private static readonly byte[] SpecialFirst = Convert.FromHexString("");
    private static readonly byte[] K1 = Convert.FromHexString("");
    private static readonly byte[] K2 = Convert.FromHexString("");
    private static readonly byte[] K3 = Convert.FromHexString("");

    public static byte[] Transform(ReadOnlySpan<byte> data)
    {
        byte[] output = new byte[data.Length];
        for (int pos = 0; pos < data.Length; pos++)
        {
            int block = pos / 256;
            int offset = pos & 255;
            byte mask;

            if (block == 0)
                mask = SpecialFirst[offset];
            else
            {
                int keyIndex = (block - 1) % 3;
                mask = keyIndex switch
                {
                    0 => K1[offset],
                    1 => K2[offset],
                    _ => K3[offset]
                };
            }
            output[pos] = (byte)(data[pos] ^ mask);
        }
        return output;
    }
}
